"use client";

const LOGO_SRC = "data:image/png;base64,";

export default function T2PLogo({ size = "normal", variant = "light" }) {
  const imgH = size === "small" ? 22 : size === "large" ? 40 : 28;
  const fontSize = size === "small" ? 14 : size === "large" ? 24 : 18;
  const textColor = variant === "dark" ? "#18181B" : "#fff";

  return (
    <a href="https://www.traintoperform.fit" target="_blank" rel="noopener noreferrer" style={{ textDecoration: "none", display: "flex", alignItems: "center", gap: size === "large" ? 12 : 8 }}>
      <img src={LOGO_SRC} alt="T2P" style={{ height: imgH, width: "auto", opacity: 0.85 }} />
      <span style={{ fontFamily: "'Bebas Neue', 'Space Mono', monospace", fontSize, color: textColor, letterSpacing: "0.08em", lineHeight: 1 }}>
        TRAIN TO <span style={{ color: "#DC2626" }}>PERFORM</span>
      </span>
    </a>
  );
}
